//! Real public retained-host schema proposals. No compile/daemon/writer or fake source grants.
#[path="../../../shared/test_scratch.rs"]mod scratch;
#[path="../../../../analyze/fixtures/report_configuration.rs"]mod report_configuration;
use dmbc::{policy_request::{AnalysisContext,PolicyInputRequest,WorkspacePolicyRequest,WorkspaceAuxiliaryQuestion as Q},request::{BuildRequest,Command},runner_host::BuildHost};
use std::{io,path::{Path,PathBuf}};
#[global_allocator]static ALLOC:mimalloc::MiMalloc=mimalloc::MiMalloc;
fn put(root:&Path,rel:&str,bytes:impl AsRef<[u8]>){let path=root.join(rel);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}
// Fixture source mutations always restore bytes/mtime, including panic/error paths.
struct Restore{path:PathBuf,bytes:Vec<u8>,modified:std::time::SystemTime}
impl Restore{fn new(path:PathBuf)->Self{Self{bytes:std::fs::read(&path).unwrap(),modified:std::fs::metadata(&path).unwrap().modified().unwrap(),path}}fn restore(&self)->io::Result<()>{std::fs::write(&self.path,&self.bytes)?;std::fs::File::options().write(true).open(&self.path)?.set_times(std::fs::FileTimes::new().set_modified(self.modified))}}
impl Drop for Restore{fn drop(&mut self){self.restore().expect("restore owned schema fixture source after mutation");}}
// An unresolved ordinary call is intentional valid analysis input: both native
// and legacy classify its result as unknown Call, not a fake value-only stub.
// No whole Checker/compile qualification is claimed for this fixture.
const SOURCE:&str="/datum/msg\n/datum/msg/good\n/datum/holder\n    var/saved\n    var/path_saved\n    proc/check()\n        saved = unknown_factory()\n        saved = \"actual text\"\n        path_saved = unknown_factory()\n        path_saved = /datum/msg/good\n        path_saved = /datum/msg/good\n";
fn fixture(label:&str,manifest:Option<&str>,overlay:&str)->(PathBuf,BuildRequest){let root=scratch::dir(label);put(&root,"code/probe.dm",SOURCE);if let Some(text)=manifest{put(&root,"deepquarry.dme",text)}put(&root,"tools/ci/lint_scopes.toml",report_configuration::with_overlay(overlay));let Command::Build(request)=dmbc::cli::parse(&["prepare-query".into(),root.join("deepquarry.dme").to_string_lossy().into_owned()]).unwrap()else{panic!("genuine public prepare parser")};let mut request=*request;request.no_cache=true;request.exact_inputs=true;request.progress_enabled=false;request.workers=1;request.timeout_seconds=Some(60);request.engine_template=None;request.bootstrap_catalog=false;request.cache_root=Some(scratch::dir(&format!("{label}-cache")));request.policy_inputs=Some(PolicyInputRequest{analysis_context:Some(AnalysisContext::OriginalAnalyze0290),workspace:Some(WorkspacePolicyRequest{root:root.clone(),recursive_roots:vec![root.join("code")],configuration:root.join("tools/ci/lint_scopes.toml")}),workspace_auxiliary:vec![Q::Untyped],..Default::default()});(root,request)}
fn report(host:&mut BuildHost,request:&BuildRequest)->String{let mut output=Vec::new();let count=host.write_schema_proposals_to(request.clone(),&mut Vec::new(),&mut output).unwrap();let text=String::from_utf8(output).unwrap();assert!(text.contains(&format!("{count} proposal(s);")));text}
const EXPECTED:&str="code/probe.dm:4: PROPOSED (not applied; a person reviews the base): SCHEMA(/datum/holder, saved, schema_text())\ncode/probe.dm:5: PROPOSED (not applied; a person reviews the base): SCHEMA(/datum/holder, path_saved, schema_path(/datum/msg))\n2 proposal(s); nothing was written (--apply does not apply a schema_path base).\n";
#[test]fn actual_schema_proposals_real_missing_and_blank_manifest_share_owned_subject_semantics(){for(label,manifest)in[("schema-real",Some("#include \"code/probe.dm\"\n")),("schema-missing",None),("schema-blank",Some("// no includes\n"))]{let(root,request)=fixture(label,manifest,"");let mut host=BuildHost::default();assert_eq!(report(&mut host,&request),EXPECTED);assert_eq!(report(&mut host,&request),EXPECTED,"warm result still runs genuine current source checks");if manifest.is_none(){assert!(!root.join("deepquarry.dme").exists(),"no fabricated physical manifest");}assert!(!root.join("__dmb_original_analysis_subject__").exists(),"private include subject never becomes a physical source");}}
#[test]fn actual_schema_proposals_apply_actual_exempt_scope_without_changing_success_footer(){let(_,request)=fixture("schema-exempt",None,"[lint.untyped]\nexempt_prefixes=['code/']\n");let mut host=BuildHost::default();assert_eq!(report(&mut host,&request),"0 proposal(s); nothing was written (--apply does not apply a schema_path base).\n");}
#[test]fn actual_schema_proposals_first_output_io_stops_and_healthy_retry_recovers(){let(_,request)=fixture("schema-output-io",None,"");let mut host=BuildHost::default();struct Fail(usize);impl io::Write for Fail{fn write(&mut self,_:&[u8])->io::Result<usize>{self.0+=1;Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{panic!("no later flush after first write error")}}let mut output=Fail(0);assert_eq!(host.write_schema_proposals_to(request.clone(),&mut Vec::new(),&mut output).unwrap_err().downcast_ref::<io::Error>().unwrap().raw_os_error(),Some(1450));assert_eq!(output.0,1);assert_eq!(report(&mut host,&request),EXPECTED);}
#[test]fn actual_schema_proposals_foreign_project_and_final_configuration_change_cannot_deliver(){
 let(root,request)=fixture("schema-configuration-freshness",Some("#include \"code/probe.dm\"\n"),"");let mut host=BuildHost::default();let mut foreign=request.clone();foreign.policy_inputs.as_mut().unwrap().workspace.as_mut().unwrap().root=scratch::dir("schema-foreign");let mut called=false;
 assert!(host.with_schema_proposals_to(foreign,&mut Vec::new(),|_,_,_|{called=true;Ok(())}).is_err());assert!(!called);
 let path=root.join("tools/ci/lint_scopes.toml");let restore=Restore::new(path.clone());
 let result=host.with_schema_proposals_to(request.clone(),&mut Vec::new(),|data,_,_|{assert_eq!(data.rows().len(),2);let mut changed=restore.bytes.clone();let at=changed.iter().position(|b|b.is_ascii_alphabetic()).unwrap();changed[at]=if changed[at].is_ascii_lowercase(){changed[at].to_ascii_uppercase()}else{changed[at].to_ascii_lowercase()};std::fs::write(&path,&changed)?;std::fs::File::options().write(true).open(&path)?.set_times(std::fs::FileTimes::new().set_modified(restore.modified))?;Ok(())});
 restore.restore().unwrap();assert!(result.is_err(),"same-size/restored-mtime configuration bytes are in final freshness closure");
}
#[test]fn actual_schema_proposals_final_source_barrier_refuses_callback_mutation(){let(root,request)=fixture("schema-final-freshness",None,"");let mut host=BuildHost::default();let path=root.join("code/probe.dm");let restore=Restore::new(path.clone());let original=restore.bytes.clone();let stamp=std::fs::metadata(&path).unwrap().modified().unwrap();let result=host.with_schema_proposals_to(request.clone(),&mut Vec::new(),|data,_,_|{assert_eq!(data.rows().len(),2);let mut changed=original.clone();let at=changed.windows(11).position(|w|w==b"actual text").unwrap();changed[at]=b'A';std::fs::write(&path,&changed)?;std::fs::File::options().write(true).open(&path)?.set_times(std::fs::FileTimes::new().set_modified(stamp))?;Ok(())});restore.restore().unwrap();assert!(result.is_err(),"report callback cannot finish with changed current source");}
